import{_ as a,o as t,c as s,a3 as r}from"./chunks/framework.B8jMSdkO.js";const g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function i(n,e,c,d,p,l){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Rust workspace, lean ports-and-adapters. <code>cypera-core</code> is pure domain — models and markdown renderers, <strong>no I/O</strong>; <code>cypera-cli</code> (package <code>cypera</code>) is the composition root — clap argv, filesystem walks, stdout/file emit. The split is the org convention: everything reconstructible from strings lives in core so it stays unit-testable without a filesystem.</p><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>cypera-core</code></td><td>domain</td><td>Pure domain logic for cypera — doc-generation models and markdown renderers</td></tr><tr><td><code>cypera-driver</code></td><td>driver</td><td>tamias-driver-cypera — pavo driver exposing a cypera workspace&#39;s engine ops (no views)</td></tr><tr><td><code>cypera-xtask</code></td><td>tooling</td><td>Workspace automation — check / test / coverage / pack / install / fmt</td></tr><tr><td><code>cypera</code></td><td>binary</td><td>cypera — reusable documentation/reference generation for the 9aia org.</td></tr></tbody></table><p>Regenerate the table above (never hand-edit it):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cypera</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crate-map</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/explanation/architecture.md</span></span></code></pre></div><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>repo sources                cypera-core (pure)           cypera-cli (IO)</span></span>
<span class="line"><span>─────────────               ─────────────────           ────────────────</span></span>
<span class="line"><span>Cargo.toml workspace   →    manifest models        →    workspace walk,</span></span>
<span class="line"><span>member Cargo.tomls          crate_map renderer          member-glob</span></span>
<span class="line"><span>src/lib.rs|main.rs          EntryScan                    expansion,</span></span>
<span class="line"><span>/// doc comments       →    config scanner         →    entry-file reads,</span></span>
<span class="line"><span>/// pub struct               renderers                    emit (stdout/--out)</span></span>
<span class="line"><span>gen-cli-docs output    →    cli page wrapper       →    stdin/file read</span></span></code></pre></div><h2 id="why-a-marker-splice" tabindex="-1">Why a marker splice <a class="header-anchor" href="#why-a-marker-splice" aria-label="Permalink to &quot;Why a marker splice&quot;">​</a></h2><p>The per-repo <code>gen-crate-map.py</code> scripts did two things: emit a standalone crate-map page <em>and</em> splice the table into <code>explanation/architecture.md</code> behind a <code>&lt;!-- crate-map --&gt;</code> marker. cypera keeps both paths: <code>--out</code> on a marker-bearing file replaces only the table rows; on any other file it writes the full generated page.</p><h2 id="what-cypera-deliberately-doesn-t-do" tabindex="-1">What cypera deliberately doesn&#39;t do <a class="header-anchor" href="#what-cypera-deliberately-doesn-t-do" aria-label="Permalink to &quot;What cypera deliberately doesn&#39;t do&quot;">​</a></h2><ul><li><strong>No upward repo discovery</strong> — <code>--repo</code> is explicit so scripts and CI stay deterministic.</li><li><strong>No rustdoc internals</strong> — <code>gen api</code> orchestrates <code>cargo doc</code> and copies <code>&lt;target&gt;/doc</code> verbatim; it does not parse rustdoc JSON. <code>crate_api</code> config only emits the rustdoc <em>link list</em>.</li><li><strong>No async, no daemon</strong> — sync binary, scoped like its siblings.</li></ul><p>See <a href="./boundaries.html">Boundaries</a> for what cypera owns and the neighbors it deliberately doesn&#39;t.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>In the org&#39;s layering — <strong>delivery</strong> (tamias, scarab, tarsi, bupha, hypha) → <strong>memory</strong> (myco, kuda) → <strong>process</strong> (sturn, cuora, mimus, cicada, lasius, sepia, peregrin) → <strong>interface</strong> (pavo).</p><p>Cypera sits <em>under</em> every layer: each repo&#39;s docs site regenerates its reference pages through cypera, and <code>cypera check</code> is the gate that keeps the org&#39;s docs contract honest. It is a library-grade tool consumed by repos, not an organism the org runs.</p>`,15)])])}const m=a(o,[["render",i]]);export{g as __pageData,m as default};
